package main
import("context";"crypto/rsa";"errors";"io";"os";"time";"custom-router/config";"custom-router/internal/boot";"custom-router/internal/controller";"custom-router/internal/identity";"custom-router/internal/manager";"custom-router/internal/validator";"custom-router/pkg/logging")
func main(){ctx:=context.Background();cfg,e:=config.Load(ctx,"config/router.yaml");if e!=nil{panic(e)};pass:=os.Getenv("CUSTOM_ROUTER_KEY_PASSPHRASE");if pass==""{panic("CUSTOM_ROUTER_KEY_PASSPHRASE is required")};board,e:=identity.LoadBoardID(cfg.DeviceCertificate);if e!=nil{panic(e)};store:=identity.FileStore{Path:cfg.DeviceKey,Passphrase:pass};key,_,e:=store.Load();if e!=nil{if !errors.Is(e,os.ErrNotExist){panic(e)};key,e=identity.GenerateRSA(2048);if e!=nil{panic(e)};if e=store.Save(key,board.PEM);e!=nil{panic(e)}};run(ctx,cfg,key,board.PEM)}
func run(ctx context.Context,cfg config.Config,key *rsa.PrivateKey,board []byte){lg:=logging.New(nil);vc:=validator.Client{Config:cfg,PrivateKey:key,BoardIDCertificate:board,Timeout:5*time.Second};cc:=controller.Client{Timeout:time.Duration(cfg.ControllerTimeoutSeconds)*time.Second};mc:=manager.Client{Timeout:time.Duration(cfg.ManagerTimeoutSeconds)*time.Second};ap:=manager.Applier{Path:"runtime/router-config.json"};seq:=boot.Sequence{Log:lg,Config:cfg,Retry:boot.RetryPolicy{Initial:time.Duration(cfg.RetryInitialMS)*time.Millisecond,Max:time.Duration(cfg.RetryMaxMS)*time.Millisecond,Ports:cfg.ValidatorPorts},Hooks:boot.Hooks{Handshake:func(c context.Context,a string)(io.ReadWriteCloser,error){return vc.Connect(c,a)},Discover:validator.Discover,ControllerConnect:cc.Connect,FetchConfig:mc.Fetch,ApplyConfig:ap.Apply}};if e:=seq.Run(ctx);e!=nil{lg.Printf("router stopped: %v",e)}}
